"use strict";
const fs = require("fs");
const path = require("path");

if (!fs.existsSync("package.json") || !fs.existsSync(path.join("prisma", "schema.prisma"))) {
  console.error("\nERROR: run this from the project root (envoys-site).");
  console.error("  You are in: " + process.cwd() + "\n");
  process.exit(1);
}

const files = {
  "middleware.ts":
    "",
  "next.config.ts":
    "",
  "mobile/lib/api.ts":
    "",
  "mobile/lib/http.ts":
    "",
  "mobile/lib/offline/cache.ts":
    "",
  "tests/lib/cors-response-headers.test.ts":
    "",
  "tests/mobile/web-session.test.ts":
    "",
};

let count = 0;
for (const rel of Object.keys(files).sort()) {
  const full = path.join(process.cwd(), rel);
  fs.mkdirSync(path.dirname(full), { recursive: true });
  fs.writeFileSync(full, Buffer.from(files[rel], "base64"));
  console.log("  wrote " + rel);
  count++;
}

console.log("\nDone. " + count + " files written.\n");
console.log("VERIFY:");
